args.content:
.page {
  max-width: 960px;
  margin: 0 auto;
  padding: 0 24px 96px;
  font-family: inherit;
}

.hero {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 24px;
  padding: 120px 0 96px;
  text-align: center;
}

.hero__title {
  margin: 0;
}

.hero__subtitle {
  max-width: 560px;
  margin: 0;
}

.benefits {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 24px;
  padding: 0 0 96px;
}

.benefit {
  display: flex;
  flex-direction: column;
  gap: 12px;
  padding: 28px;
  border: 1px solid var(--g-color-line-generic);
  border-radius: 16px;
}

.benefit p,
.benefit h3 {
  margin: 0;
}

.cta {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 24px;
  padding: 64px 24px;
  text-align: center;
  border: 1px solid var(--g-color-line-generic);
  border-radius: 16px;
}

.cta h2 {
  margin: 0;
}

@media (max-width: 720px) {
  .benefits {
    grid-template-columns: 1fr;
  }

  .hero {
    padding: 80px 0 64px;
  }
}

